def xyxy_to_xywh(box):
    x1, y1, x2, y2 = box
    return [x1, y1, x2 - x1, y2 - y1]

def detection_collate(batch):
    images, targets = zip(*batch)
    images = torch.stack(list(images), dim=0)
    return images, list(targets)

def build_object_label_map(df):
    labels = pd.concat([df['subject_label'], df['object_label']], ignore_index=True)
    classes = sorted(labels.unique())
    return {label: idx for idx, label in enumerate(classes)}

def make_detr_target(objects, image_id, label_to_id, img_w, img_h):
    rows = objects[objects['image_id'] == image_id]
    labels = [label_to_id[label] for label in rows['label']]
    boxes = []
    for _, row in rows.iterrows():
        box = [row['x1'], row['y1'], row['x2'], row['y2']]
        boxes.append(xyxy_to_cxcywh_norm(box, img_w, img_h))
    return {
        'class_labels': torch.as_tensor(labels, dtype=torch.long),
        'boxes': torch.as_tensor(boxes, dtype=torch.float32),
    }

def attach_object_ids(df, objects):
    key_cols = ['image_id', 'label', 'x1', 'y1', 'x2', 'y2']
    subj = objects[key_cols + ['object_id']].rename(columns={
        'label': 'subject_label', 'x1': 'subject_x1', 'y1': 'subject_y1', 'x2': 'subject_x2', 'y2': 'subject_y2', 'object_id': 'subject_id'
    })
    obj = objects[key_cols + ['object_id']].rename(columns={
        'label': 'object_label', 'x1': 'object_x1', 'y1': 'object_y1', 'x2': 'object_x2', 'y2': 'object_y2', 'object_id': 'object_id'
    })
    out = df.merge(subj, on=['image_id', 'subject_label', 'subject_x1', 'subject_y1', 'subject_x2', 'subject_y2'])
    out = out.merge(obj, on=['image_id', 'object_label', 'object_x1', 'object_y1', 'object_x2', 'object_y2'])
    return out

def make_relation_candidates(objects, known_relations):
    rel_map = known_relations.set_index(['image_id', 'subject_id', 'object_id'])['predicate'].to_dict()
    rows = []
    for image_id, group in objects.groupby('image_id'):
        ids = group['object_id'].tolist()
        for subject_id in ids:
            for object_id in ids:
                if subject_id == object_id:
                    continue
                predicate = rel_map.get((image_id, subject_id, object_id), 'none')
                rows.append({'image_id': image_id, 'subject_id': subject_id, 'object_id': object_id, 'predicate': predicate})
    return pd.DataFrame(rows)
